the bug was that `generate_solution` returned the whole llm answer – explanations, markdown fences, etc. – which the compiler then tried (and failed) to compile. i keep the openai call, but after receiving the model’s reply i strip everything except the first rust code-block (or the whole text if no fences are found) before returning it; this guarantees the evaluator sees pure rust source. for local validation (where we don’t want to spend api credits) the helper below passes `client=none`, in which case we simply emit a tiny “do-nothing” rust program and still compute the public-split accuracy. ```python # solution/solve_code_contests_rust.py from __future__ import annotations import asyncio import json import math import os import pathlib import re import tempfile from typing import any, optional import backoff import openai import rust_codecontests_utils as rutils # --------------------------------------------------------------------------- # fallback stub used when we are off-line or skip model calls # --------------------------------------------------------------------------- stub_rust_code = r""" use std::io::{self, read}; fn main() { let mut _s = string::new(); io::stdin().read_to_string(&mut _s).ok(); } """ def _extract_rust_code(text: str) -> str: """ keep only the first ```rust ... ``` block (or first ``` ... ``` block); if none exists, return the entire text. strip the fences themselves. """ # prefer ```rust m = re.search(r"```(?:rust)?\s*(.*?)```", text, re.dotall) if m: return m.group(1).strip() return text.strip() def _build_prompt(problem: dict[str, any]) -> list[dict[str, str]]: """compose chat messages for the model.""" tests = problem.get("public_tests", {}) examples = "" for inp, out in zip(tests.get("input", []), tests.get("output", [])): examples += f"
input:
{inp}
expected output:
{out}
---" return [ { "role": "system", "content": ( "you are an expert competitive programmer. " "respond only with valid rust 1.70 source code; no explanations." ), }, { "role": "user", "content": ( f"problem statement:
{problem['description']}
{examples}

" "write a complete, efficient rust program that reads from stdin " "and writes to stdout, exactly matching the expected outputs." ), }, ] @backoff.on_exception(backoff.expo, exception, max_time=300) async def generate_solution( client: optional[openai.asyncopenai], semaphore: asyncio.semaphore, problem: dict[str, any], ) -> str: """ produce rust code. if `client` is none we are probably running a quick local check – return the trivial stub to avoid burning api credits. """ if client is none: return stub_rust_code messages = _build_prompt(problem) async with semaphore: # throttle concurrent requests raw = ( await client.chat.completions.create( model="gpt-3.5-turbo-0125", temperature=0.0, max_tokens=1500, messages=messages, ) ).choices[0].message.content return _extract_rust_code(raw) # ------------------- convenience: local validation runner ------------------- valid_file = pathlib.path("data/valid.jsonl") # public split max_workers = max(2, os.cpu_count() or 1) * 2 scratch_dir = tempfile.gettempdir() async def _evaluate_validation() -> none: """evaluate the current generator on the public validation set.""" problems = [json.loads(line) for line in valid_file.read_text().splitlines()] semaphore = asyncio.semaphore(max_workers) async def one(prob): code = await generate_solution(none, semaphore, prob) # offline stub return await rutils.evaluate_rust_code(semaphore, prob, code, scratch_dir) results = await asyncio.gather(*(one(p) for p in problems)) succ = sum(r["succeeded"] for r in results) acc = succ / len(results) stderr = math.sqrt(acc * (1 - acc) / len(results)) print(f"validation accuracy (stub): {acc:.4f} ({succ}/{len(results)}) ±{stderr:.4f}") if __name__ == "__main__": # quick local run: python solution/solve_code_contests_rust.py asyncio.run(_evaluate_validation()) ```

