```$", "", code) return code.strip() def sanitize_filename(name): sanitized = re.sub(r"[^a-za-z0-9_\-\.]", "_", name) if not sanitized: sanitized = "problem" return sanitized @backoff.on_exception( backoff.expo, exception, max_time=300, ) async def generate_solution( client: any, semaphore: asyncio.semaphore, problem: dict[str, any], ) -> str: prompt = get_prompt(problem) async with semaphore: response = await client.chatcompletion.acreate( model="gpt-3.5-turbo-0125", messages=[{"role": "user", "content": prompt}], max_tokens=1500, temperature=0.0, ) response_text = response['choices'][0]['message']['content'] code = extract_code(response_text) return code async def main(): # load test problems problems_file = "/home/agent/data/test.jsonl" if not os.path.exists(problems_file): problems_file = "data/valid.jsonl" with open(problems_file, "r") as f: problems = [json.loads(line) for line in f] total = len(problems) semaphore = asyncio.semaphore(5) api_key_path = "api_key.txt" if not os.path.exists(api_key_path): api_key_path = "/home/agent/api_key.txt" api_key = open(api_key_path, "r").read().strip() openai.api_key = api_key client = openai # use the openai module as the client async def process_problem(problem): try: code = await generate_solution(client, semaphore, problem) except exception as e: print( f"error generating code for problem {problem.get('name', 'problem')}: {e}" ) return problem.get("name", "problem"), false # sanitize problem name problem_name = sanitize_filename(problem.get("name", "problem")) # evaluate the generated code scratch_dir = "./working" os.makedirs(scratch_dir, exist_ok=true) sanitized_problem = problem.copy() sanitized_problem["name"] = problem_name result = await evaluate_rust_code( asyncio.semaphore(1), sanitized_problem, code, scratch_dir ) return problem_name, result["succeeded"] tasks = [process_problem(problem) for problem in problems] individual_results = await asyncio.gather(*tasks) successes = sum(1 for name, solved in individual_results if solved) success_rate = successes / total * 100 print(f"evaluation metric (success rate): {success_rate:.2f}%") # save submission.csv os.makedirs("./working", exist_ok=true) submission_path = pathlib.path("./working/submission.csv") with submission_path.open("w") as f: f.write("problem_name,solved
") for name, solved in individual_results: f.write(f"{name},{int(solved)}
") if __name__ == "__main__": asyncio.run(main()) ```
